<script setup>
import {computed,onMounted,onUnmounted,ref,reactive,watch} from 'vue'
import {api,state,notify} from '../lib'
import Icon from './Icon.vue'
import RoundedSelect from './RoundedSelect.vue'
import VirtualList from './VirtualList.vue'
import Modal from './Modal.vue'
const storage=ref(''),directory=ref(''),trail=ref([]),files=ref([]),items=ref([]),query=ref(''),loading=ref(false),busy=ref(false),progress=ref({}),taskId=ref(''),matching=ref(null),confirmation=ref(null),root=ref('')
const match=reactive({tmdb:'',kind:'movie'})
const pools=computed(()=>state.storages.filter(s=>s.enabled).map(s=>({value:s.id,label:s.name,provider:s.type})))
const filtered=computed(()=>files.value.filter(f=>f.isDir||/\.(mp4|mkv|avi|mov|wmv|flv|webm|m4v|ts|m2ts|mkvb|rmvb|rm|3gp|mpg|mpeg|iso|strm)$/i.test(f.name)).filter(f=>f.name.toLowerCase().includes(query.value.toLowerCase())))
let alive=true,request=0,timer
const status=item=>({ok:'已完成',pending:'待刮削',miss:'未识别',doubt:'待确认',error:'失败'}[item?.status]||'未识别')
function result(file){return items.value.find(i=>i.path===file.name)}
async function load(){const ticket=++request,sid=storage.value,dir=directory.value;if(!sid)return;loading.value=true;try{const data=await api(`/directory-scrape/files?${new URLSearchParams({storageId:sid,directory:dir})}`);if(alive&&ticket===request){files.value=data.files;items.value=data.items;taskId.value=data.taskId;directory.value=data.directory;if(!trail.value.length)root.value=data.directory}}catch(e){if(alive&&ticket===request)notify(e.message,true)}finally{if(alive&&ticket===request)loading.value=false}}
watch(storage,()=>{request++;directory.value='';trail.value=[];files.value=[];items.value=[];load()})
watch(pools,options=>{if(!options.some(s=>s.value===storage.value))storage.value=options[0]?.value||''},{immediate:true})
function enter(file){trail.value.push({id:file.id,name:file.name});directory.value=file.id;load()}
function jump(index){trail.value=trail.value.slice(0,index+1);directory.value=trail.value.at(-1)?.id||root.value;load()}
function back(){jump(trail.value.length-2)}
function identify(file){matching.value=file;Object.assign(match,{tmdb:result(file)?.tmdb||'',kind:result(file)?.kind||'movie'})}
function choose(file){if(file.isDir)enter(file);else identify(file)}
async function execute(action,ids=confirmation.value?.ids||[]){busy.value=true;try{progress.value=await api(`/directory-scrape/${action}`,'POST',{storageId:storage.value,directory:directory.value,ids,...(action==='match'?{tmdb:Number(match.tmdb),kind:match.kind,group:!!matching.value?.isDir}:{})});confirmation.value=null;matching.value=null;notify(action==='reset'?'识别结果重置已启动':action==='identify'?'目录识别已启动':'目录刮削已启动')}catch(e){notify(e.message,true)}finally{busy.value=false}}
async function poll(){try{const old=progress.value;const data=await api('/strm-scrape/status');if(!alive)return;progress.value=data;if(old.running&&!data.running){await load();notify(data.message||'刮削已结束',!!data.error||data.failed>0)}}catch(e){if(alive)notify(e.message,true)}finally{if(alive)timer=setTimeout(poll,2000)}}
async function stop(){try{await api('/strm-scrape/stop','POST',{});notify('正在停止刮削任务')}catch(e){notify(e.message,true)}}
onMounted(poll)
onUnmounted(()=>{alive=false;request++;clearTimeout(timer)})
</script>
<template>
 <section class="directory-scrape-panel" aria-label="目录刮削">
  <header class="directory-scrape-toolbar"><RoundedSelect v-model="storage" label="刮削存储池" :options="pools"/><button class="icon-btn" aria-label="上级目录" :disabled="!trail.length||loading" @click="back"><Icon name="ArrowUp"/></button><div class="directory-toolbar-spacer"/><div class="directory-toolbar-controls"><button v-if="progress.running" class="icon-btn" aria-label="停止目录刮削" @click="stop"><Icon name="Square"/></button><span class="directory-item-count" role="status" aria-label="当前目录数量">{{filtered.length}} 项</span><button class="icon-btn" aria-label="刷新目录" :disabled="loading" @click="load"><Icon name="RefreshCw" :class="{spin:loading}"/></button></div><div class="search-field"><Icon name="Search"/><input v-model="query" aria-label="搜索目录媒体" placeholder="搜索文件名称"/></div></header>
  <nav class="scrape-file-path" aria-label="刮削目录路径"><button class="text-btn" :disabled="loading" @click="jump(-1)"><Icon name="Folder"/>根目录</button><template v-for="(crumb,index) in trail" :key="crumb.id"><Icon name="ChevronRight" :size="14"/><button class="text-btn" :disabled="loading" @click="jump(index)">{{crumb.name}}</button></template></nav>
  <div v-if="progress.running" class="directory-scrape-progress"><span>{{progress.message}} · {{progress.done||0}} / {{progress.total||0}}</span><progress :value="progress.done||0" :max="progress.total||1"/></div>
  <div class="directory-scrape-list"><p v-if="loading" class="small-empty">正在读取目录…</p><VirtualList v-else :items="filtered" :row-height="56"><template #default="{item}"><article class="directory-scrape-row scrape-file-row"><button class="text-btn directory-file-name" @click="choose(item)"><Icon :name="item.isDir?'Folder':'FileVideo'" :size="24" :class="{'folder-color':item.isDir}"/><span :data-tooltip="item.name" data-tooltip-stationary data-tooltip-delay="300">{{item.name}}</span></button><span v-if="result(item)?.tmdb" class="directory-recognized" :data-tooltip="result(item).matchedTitle||result(item).title">{{result(item).matchedTitle||result(item).title}} · TMDB {{result(item).tmdb}}</span><small v-else-if="!item.isDir" class="directory-media-status">{{status(result(item))}}</small><div class="scrape-folder-actions"><button class="text-btn" :aria-label="`重置 ${item.name}`" :disabled="busy||progress.running" @click="confirmation={action:'reset',ids:[item.id],name:item.name}"><Icon name="RotateCcw"/>重置</button><button class="text-btn" :aria-label="`识别 ${item.name}`" :disabled="busy||progress.running" @click="identify(item)"><Icon name="ScanSearch"/>识别</button></div></article></template></VirtualList><p v-if="!loading&&!filtered.length" class="small-empty">当前目录没有媒体文件</p></div>
 </section>
 <Modal v-if="confirmation" title="重置目录识别结果" compact confirmation @close="!busy&&(confirmation=null)"><div class="modal-body">重置「{{confirmation.name}}」的识别和匹配记录，保留媒体、NFO和海报文件。</div><footer class="modal-footer"><button class="btn" :disabled="busy" @click="confirmation=null">取消</button><button class="btn primary" :disabled="busy" @click="execute(confirmation.action)">确认重置</button></footer></Modal>
 <Modal v-if="matching" title="手动识别目录媒体" compact @close="!busy&&(matching=null)"><div class="modal-body"><p :data-tooltip="matching.name">{{matching.name}}</p><div class="form-grid"><label>媒体类型<RoundedSelect v-model="match.kind" label="媒体类型" :options="[{value:'movie',label:'电影'},{value:'tv',label:'剧集'}]"/></label><label>TMDB ID<input v-model="match.tmdb" aria-label="TMDB ID" inputmode="numeric"/></label></div></div><footer class="modal-footer"><button class="btn" @click="matching=null">取消</button><button class="btn primary" :disabled="busy||progress.running||!/^\d+$/.test(String(match.tmdb))||Number(match.tmdb)<1" @click="execute('match',[matching.id])">识别并刮削</button></footer></Modal>
</template>
<style scoped>
.directory-scrape-row.scrape-file-row{display:flex;height:56px;gap:12px;padding:8px 14px}.directory-scrape-row .directory-file-name{flex:1;min-width:0;justify-content:flex-start}.directory-file-name svg{flex:none}.directory-file-name span{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.directory-toolbar-spacer{flex:1}.directory-item-count{padding:5px 10px;border-radius:7px;background:var(--primary-soft);color:var(--primary);font-size:12px;white-space:nowrap}.scrape-file-path{display:flex;align-items:center;gap:5px;padding:10px 14px;overflow:auto;white-space:nowrap;scrollbar-width:none;border-block:1px solid var(--border)}.scrape-file-path button{flex:none;color:var(--muted);font-size:14px}.scrape-file-path button:hover{color:var(--primary)}.directory-scrape-row>.scrape-folder-actions{display:flex;flex:none;gap:12px;opacity:0}.scrape-folder-actions .text-btn{gap:4px}.directory-scrape-row:hover,.directory-scrape-row:focus-within{background:var(--primary-soft)}.directory-scrape-row:hover>.scrape-folder-actions,.directory-scrape-row:focus-within>.scrape-folder-actions{opacity:1}.directory-recognized{flex:1;min-width:0;color:var(--primary);font-size:12px}.directory-media-status{color:var(--muted)}
.directory-scrape-panel{border:1px solid var(--border);border-radius:10px;background:var(--surface);overflow:hidden;min-width:0}.directory-scrape-toolbar{display:flex;align-items:center;gap:10px;padding:14px;flex-wrap:wrap}.directory-scrape-toolbar>.rounded-select{width:180px;max-width:100%}.directory-scrape-location{flex:1;min-width:60px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px}.directory-scrape-toolbar .search-field{width:200px;max-width:100%}.directory-scrape-actions{display:flex;align-items:center;gap:10px;padding:10px 14px;border-block:1px solid var(--border)}.directory-scrape-actions>span{margin-right:auto;color:var(--muted);font-size:13px}.directory-scrape-list{height:min(620px,65dvh)}.directory-scrape-columns,.directory-scrape-row{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr) 90px 70px;align-items:center;gap:16px;padding:0 16px;font-size:13px}.directory-scrape-columns{height:38px;background:var(--layer-frame);color:var(--muted)}.directory-scrape-row{height:54px;border-bottom:1px solid var(--border)}.directory-scrape-row>div,.directory-scrape-row .text-btn{display:flex;align-items:center;gap:10px;min-width:0}.directory-scrape-row input{width:16px;flex:none}.directory-scrape-row .text-btn{max-width:100%}.directory-scrape-row svg{flex:none}.directory-scrape-row span{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.directory-scrape-progress{padding:12px 16px;display:grid;gap:8px;font-size:13px}.directory-scrape-progress progress{width:100%}@media(max-width:600px){.directory-scrape-columns,.directory-scrape-row{grid-template-columns:minmax(0,1fr) 64px;gap:10px;padding-inline:10px}.directory-scrape-columns>:nth-child(2),.directory-scrape-columns>:nth-child(3),.directory-scrape-row>:nth-child(2),.directory-scrape-row>:nth-child(3){display:none}.directory-scrape-toolbar .search-field{width:auto;flex:1}}
@media(hover:none){.directory-scrape-row>.scrape-folder-actions{opacity:1}}@media(max-width:600px){.directory-scrape-row>.scrape-folder-actions{display:flex;gap:6px}.directory-scrape-row.scrape-file-row>.directory-recognized,.directory-scrape-row.scrape-file-row>.directory-media-status{display:none}.scrape-folder-actions .text-btn{font-size:12px}}
</style>
<style scoped>
.directory-toolbar-controls{display:flex;align-items:center;gap:10px;flex:none}
@media(max-width:600px){.directory-scrape-toolbar>.rounded-select{width:auto;flex:1;min-width:0}.directory-scrape-toolbar>.directory-toolbar-spacer{display:none}.directory-scrape-toolbar>.search-field{flex:1 0 100%;width:100%}}
</style>
